sys_ws_operation.operation_script:
(function process(request, response) {
    try {
        var incidentId = request.pathParams.incident_id;

        if (!incidentId) {
            response.setStatus(400);
            response.setBody({ error: 'Missing incident_id path parameter' });
            return;
        }

        // Verify incident exists
        var incGr = new GlideRecord('incident');
        if (!incGr.get(incidentId)) {
            response.setStatus(404);
            response.setBody({ error: 'Incident not found: ' + incidentId });
            return;
        }

        var investigator = new global.InvestigationService(incidentId);
        var reportSysId = investigator.generateReport();

        if (reportSysId) {
            response.setStatus(200);
            response.setBody({
                result: {
                    report_sys_id: reportSysId,
                    status: 'completed',
                    message: 'Investigation report generated successfully',
                },
            });
        } else {
            response.setStatus(500);
            response.setBody({ error: 'Failed to generate investigation report' });
        }
    } catch (e) {
        gs.error('AI Investigation API: Error in investigate - ' + e);
        response.setStatus(500);
        response.setBody({ error: 'Internal server error: ' + e });
    }
})(request, response);
